import { Button } from '@/components/ds/ui/button';
import { CodeWindow } from '@/components/ds/ui/code-window';
import { cx } from '@/components/ds/ui/cx';
import { DotGrid } from '@/components/ds/ui/dot-grid';
import { Section } from '@/components/ds/ui/section';
import { Highlighted } from '@/components/ds/ui/section-heading';

export type HeroProps = {
	variant?: 'centered' | 'product';
	eyebrow?: string;
	headline: string;
	highlight?: string;
	sub: string;
	primaryCta: { label: string; href: string };
	secondaryCta?: { label: string; href: string };
	media?: { type: 'agent-setup'; prompt: string } | { type: 'code'; title: string; code: string } | { type: 'none' };
	checks?: string[];
};

const FIELD_LEFT = ['o o  oo o', ' xo o  o ', 'o oo x o ', ' o  o oo ', 'oo x  o o', ' o oo  o '];
const FIELD_RIGHT = ['o  oo o o', ' o o  xo ', 'o x oo o ', ' oo  o o ', 'o o  x oo', ' o oo  o '];

export function Hero({ variant = 'centered', eyebrow, headline, highlight, sub, primaryCta, secondaryCta, media = { type: 'none' }, checks = [] }: HeroProps) {
	const centered = variant === 'centered';
	return (
		<Section block="hero">
			<div className={cx('relative flex flex-col gap-10', centered ? 'items-center text-center' : 'md:flex-row md:items-center md:justify-between')}>
				{centered ? (
					<>
						<div className="absolute left-0 top-0 hidden lg:block"><DotGrid pattern={FIELD_LEFT} size="sm" /></div>
						<div className="absolute right-0 top-0 hidden lg:block"><DotGrid pattern={FIELD_RIGHT} size="sm" /></div>
					</>
				) : null}
				<div className={cx('relative flex max-w-3xl flex-col gap-6', centered && 'items-center')}>
					{eyebrow ? <p className="text-body-sm text-fg-muted">{eyebrow}</p> : null}
					<h1 className="text-h2 text-balance md:text-h1 lg:text-display">
						<Highlighted text={headline} highlight={highlight} className="text-brand" />
					</h1>
					<p className="max-w-xl text-body-lg text-fg-muted text-pretty">{sub}</p>
					<div className="flex flex-wrap items-center gap-3">
						<Button variant="primary" href={primaryCta.href}>{primaryCta.label}</Button>
						{secondaryCta ? <Button variant="secondary" href={secondaryCta.href}>{secondaryCta.label}</Button> : null}
					</div>
					{checks.length ? (
						<ul className="flex flex-wrap gap-x-6 gap-y-2 text-body-sm text-fg-muted">
							{checks.slice(0, 3).map((check) => (
								<li key={check} className="flex items-center gap-2"><span aria-hidden className="size-2 rounded-full bg-brand" />{check}</li>
							))}
						</ul>
					) : null}
				</div>
				{media.type !== 'none' ? (
					<div className={cx('relative w-full', centered ? 'max-w-2xl' : 'md:max-w-md')}>
						<div className="rounded-window bg-blue-80 p-2">
							{media.type === 'agent-setup' ? <CodeWindow title="agent setup" code={media.prompt} tone="light" /> : <CodeWindow title={media.title} code={media.code} tone="dark" />}
						</div>
					</div>
				) : null}
			</div>
		</Section>
	);
}
